// ====== 1. Proto 文件 (Protos/user.proto) ======
// syntax = "proto3";
// option csharp_namespace = "GrpcDemo.Protos";
// message GetUserRequest { int32 id = 1; }
// message CreateUserRequest { string name = 1; string email = 2; }
// message User { int32 id = 1; string name = 2; string email = 3; }
// service UserService {
//     rpc GetUser (GetUserRequest) returns (User);
//     rpc CreateUser (CreateUserRequest) returns (User);
//     rpc ListUsers (Empty) returns (stream User);
// }

// ====== 2. 服务端实现 ======
using Grpc.Core;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

public class UserServiceImpl : UserService.UserServiceBase
{
    private readonly IUserRepository _repo;
    private readonly ILogger<UserServiceImpl> _logger;

    public UserServiceImpl(IUserRepository repo, ILogger<UserServiceImpl> logger)
    {
        _repo = repo;
        _logger = logger;
    }

    // 一元 RPC
    public override async Task<User> GetUser(GetUserRequest request, ServerCallContext context)
    {
        var user = await _repo.GetByIdAsync(request.Id);
        if (user == null)
            throw new RpcException(new Status(StatusCode.NotFound, $"User {request.Id} not found"));
        return new User { Id = user.Id, Name = user.Name, Email = user.Email };
    }

    // 服务端流式 RPC
    public override async Task ListUsers(
        Empty request,
        IServerStreamWriter<User> responseStream,
        ServerCallContext context)
    {
        var users = await _repo.GetAllAsync();
        foreach (var user in users)
        {
            // CancellationToken 感知：客户端断开时停止写入
            context.CancellationToken.ThrowIfCancellationRequested();
            await responseStream.WriteAsync(new User
            {
                Id = user.Id, Name = user.Name, Email = user.Email
            });
        }
    }
}

// ====== 3. 客户端拦截器（日志 + 认证） ======
public class AuthLoggingInterceptor : Interceptor
{
    private readonly ILogger<AuthLoggingInterceptor> _logger;
    private readonly string _token;

    public AuthLoggingInterceptor(ILogger<AuthLoggingInterceptor> logger, string token)
    {
        _logger = logger;
        _token = token;
    }

    public override AsyncUnaryCall<TResponse> AsyncUnaryCall<TRequest, TResponse>(
        TRequest request,
        ClientInterceptorContext<TRequest, TResponse> context,
        AsyncUnaryCallContinuation<TRequest, TResponse> continuation)
    {
        // 附加认证 Metadata
        var headers = context.Options.Headers ?? new Metadata();
        headers.Add("authorization", $"Bearer {_token}");
        var options = context.Options.WithHeaders(headers);
        var newContext = new ClientInterceptorContext<TRequest, TResponse>(
            context.Method, context.Host, options);

        _logger.LogInformation("gRPC call: {Method}", context.Method.FullName);
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var call = continuation(request, newContext);

        return new AsyncUnaryCall<TResponse>(
            call.ResponseAsync.ContinueWith(t =>
            {
                sw.Stop();
                _logger.LogInformation("gRPC {Method} took {Ms}ms",
                    context.Method.FullName, sw.ElapsedMilliseconds);
                return t.Result;
            }),
            call.ResponseHeadersAsync,
            call.GetStatus,
            call.GetTrailers,
            call.Dispose);
    }
}

// ====== 4. 服务端拦截器（统一异常处理） ======
public class ExceptionInterceptor : Interceptor
{
    private readonly ILogger<ExceptionInterceptor> _logger;

    public ExceptionInterceptor(ILogger<ExceptionInterceptor> logger) => _logger = logger;

    public override async Task<TResponse> UnaryServerHandler<TRequest, TResponse>(
        TRequest request,
        ServerCallContext context,
        UnaryServerMethod<TRequest, TResponse> continuation)
    {
        try
        {
            return await continuation(request, context);
        }
        catch (RpcException) { throw; } // gRPC 原生异常不包装
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unhandled exception in {Method}", context.Method);
            throw new RpcException(new Status(StatusCode.Internal, "Internal server error"));
        }
    }
}

// ====== 5. 注册 ======
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddGrpc(options =>
{
    options.Interceptors.Add<ExceptionInterceptor>(); // 服务端拦截器
    options.MaxReceiveMessageSize = 4 * 1024 * 1024; // 4MB
    options.MaxSendMessageSize = 4 * 1024 * 1024;
});
builder.Services.AddGrpcClient<UserService.UserServiceClient>(options =>
{
    options.Address = new Uri("https://localhost:5001");
}).AddInterceptor<AuthLoggingInterceptor>(); // 客户端拦截器

var app = builder.Build();
app.UseGrpcWeb(); // 启用 gRPC-Web
app.MapGrpcService<UserServiceImpl>().EnableGrpcWeb();
app.Run();
